import sys

def find_smallest_n(s, sub):
    s = list(s)
    sub_len = len(sub)
    k = str(len(s) - len(sub))

    def can_form_number():
        temp = s[:]
        for char in sub:
            if char in temp:
                temp.remove(char)
            else:
                return False
        return True

    for i in range(10**len(k), 10**(len(k)+1)):
        str_i = str(i)
        combined = sub + str_i
        if sorted(combined) == sorted(s) and can_form_number():
            return int(''.join(sorted(s, key=lambda x: (x != '0', x))[:len(s)-len(str_i)] + str_i))

    return -1

input = sys.stdin.read().strip().split('\n')
s = input[0]
sub = input[1]

result = find_smallest_n(s, sub)
print(result)
